package com.rioikeda.newslisten.architecture

enum class OperationKind { COMMAND, QUERY }

enum class QueryEvidence { PROBE, STRUCTURAL }

/**
 * 台帳の行。1 つの公開操作（interface と実装は 1 行に寄せる）の分類。
 *
 * - [signatures] は overload を持つ行だけが書く。省いた行は、その ID の signature がちょうど 1 つであることを要求する。
 * - [facade] は android-slice-skeleton-03 が印を付ける欄（文字列）。
 */
data class LedgerRow(
    val id: String,
    val kind: OperationKind,
    val evidence: QueryEvidence? = null,
    val aliases: Set<String> = emptySet(),
    val signatures: Set<String>? = null,
    val specId: String? = null,
    val facade: String? = null,
    val reason: String,
)

/**
 * 本番の台帳。新しい操作を足す slice が 1 行を足す。
 *
 * - 公開操作の全件が 1 行に対応する（列挙の結果との 1 対 1 の照合は `LedgerChecks.reconcile`）。
 * - 効果を持ちうる型の `QUERY` は `PROBE`（各 context の `*QueryProbes.kt` が実行して書込を観測する）。
 *   `STRUCTURAL` は、宣言する型と操作の引数が効果を持たないことを機械的に確かめた値・純粋関数だけ。
 * - interface と実装は 1 行に寄せ、実装の ID を `aliases` に持つ。
 */
object OperationLedger {
    private fun query(
        id: String,
        reason: String,
        specId: String? = null,
        aliases: Set<String> = emptySet(),
        facade: String? = null,
    ) = LedgerRow(id, OperationKind.QUERY, QueryEvidence.PROBE, aliases, specId = specId, facade = facade, reason = reason)

    private fun structural(id: String, reason: String) =
        LedgerRow(id, OperationKind.QUERY, QueryEvidence.STRUCTURAL, reason = reason)

    private fun command(
        id: String,
        reason: String,
        specId: String? = null,
        aliases: Set<String> = emptySet(),
        facade: String? = null,
    ) = LedgerRow(id, OperationKind.COMMAND, aliases = aliases, specId = specId, facade = facade, reason = reason)

